#include <bits/stdc++.h>
using namespace std;

int leastInterval(vector<char>& tasks, int n) {
    int freq[26] = {0};
    for (char t : tasks) freq[t - 'A']++;
    priority_queue<int> heap;
    for (int f : freq) if (f > 0) heap.push(f);
    queue<pair<int,int>> cooldown;
    int time = 0;

    while (!heap.empty() || !cooldown.empty()) {
        time++;
        if (!heap.empty()) {
            int count = heap.top() - 1;
            heap.pop();
            if (count > 0) cooldown.push({count, time + n});
        }
        if (!cooldown.empty() && cooldown.front().second == time) {
            heap.push(cooldown.front().first);
            cooldown.pop();
        }
    }
    return time;
}

int main() {
    vector<char> t1 = {'A', 'A', 'A', 'B', 'B', 'B'};
    cout << leastInterval(t1, 2) << endl;
    vector<char> t2 = {'A', 'A', 'A', 'B', 'B', 'B'};
    cout << leastInterval(t2, 0) << endl;
    return 0;
}

